package com.fream.back.domain.m53.entity;

import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.global.entity.Xzh80Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Table(
        indexes = {
                @Index(name = "idx_user_id", columnList = "user_id"),
                @Index(name = "idx_is_default", columnList = "is_default")
        }
)
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xms98 extends Xzh80Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xjm45 user;

    @Column(nullable = false)
    private String recipientName;

    @Column(nullable = false)
    private String phoneNumber;

    @Column(nullable = false)
    private String zipCode;

    @Column(nullable = false)
    private String address;

    private String detailedAddress;

    @Column(name = "is_default")
    private boolean isDefault;


    public void updateAddress(String recipientName, String phoneNumber, String zipCode,
                              String address, String detailedAddress, Boolean isDefault) {
        if (recipientName != null) {
            this.recipientName = recipientName;
        }
        if (phoneNumber != null) {
            this.phoneNumber = phoneNumber;
        }
        if (zipCode != null) {
            this.zipCode = zipCode;
        }
        if (address != null) {
            this.address = address;
        }
        if (detailedAddress != null) {
            this.detailedAddress = detailedAddress;
        }
        if (isDefault != null) {
            this.isDefault = isDefault;
        }
    }


    public void assignUser(Xjm45 user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }
}package com.fream.back.global.config;

import com.querydsl.jpa.impl.JPAQueryFactory;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@RequiredArgsConstructor
public class Xzj77Config {

    private final EntityManager entityManager;

    @Bean
    public JPAQueryFactory jpaQueryFactory() {
        return new JPAQueryFactory(entityManager);
    }
}

